namespace Andora\Web\Route\Admin\Package;

defined("ANDORA") or die("Forbidden");

// Posted (without init) by the answer that replaced the files of a package:
// Page::onMigrateProcess runs install / upgrade in this new request and
// shows the result. Rendered only while the request runs.
class FormMigrate extends \Andora\Web\Component\Form
{
    public function formRenderAJAX($options = null)
    {
        ?>

        <div class="text-center mb-8">
            <h1 class="text-4xl font-bold"><?php $this->language->render("page.title"); ?></h1>
            <p class="mt-3 text-lg text-base-content/70">
                <?php $this->language->render("migrating"); ?>
            </p>
        </div>

        <?php
    }

    public function renderContainer($options = null)
    {
        echo "<div class=\"w-full max-w-[400px] flex flex-col\" id=\"" . $this->id . "\">";
        $this->renderAJAX();
        echo "</div>";
    }

}
